TEMPLATE='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>{title}原型</title><link rel="stylesheet" href="module-style.css"><style>.page{{height:100vh;padding:12px;background:#f5f6f8}}.card{{height:100%;display:flex;flex-direction:column}}.head{{height:56px;border-bottom:1px solid #e5eaf2;display:flex;align-items:center;padding:0 18px}}.head h2{{margin:0}}.query{{display:flex;gap:10px;align-items:end;padding:14px;border-bottom:1px solid #eef2f6;flex-wrap:wrap}}.query label{{font-weight:700}}.query input,.query select{{height:36px;border:1px solid #dbe3ef;border-radius:5px;padding:0 12px;display:block;margin-top:4px}}.content{{flex:1;overflow:auto}}.btn{{height:38px;border:1px solid #dbe3ef;background:#fff;border-radius:5px;padding:0 18px;cursor:pointer}}.btn.primary{{background:#1677ff;color:#fff}}.toast{{display:none;position:fixed;right:20px;bottom:20px;background:#101828;color:#fff;border-radius:8px;padding:12px 16px}}.edit{{display:none;height:100%;flex-direction:column}}.list{{height:100%;display:flex;flex-direction:column}}.grid4{{display:grid;grid-template-columns:repeat(4,1fr);gap:16px 40px;padding:16px 20px;border-bottom:1px solid #eef2f6}}.summary{{height:64px;background:#101828;color:#fff;display:flex;align-items:center;gap:24px;padding:0 18px}}.summary b{{font-family:Consolas}}</style></head><body><div class="page"><div class="card"><div class="list" id="list"><div class="head"><h2>{title}列表</h2><div style="margin-left:auto"><button class="btn primary" onclick="showEdit('new')">新建</button></div></div><div class="query">{filters}<button class="btn primary">查询</button><button class="btn">重置</button></div><div class="content"><table class="matrix"><tr>{list_heads}<th>操作</th></tr><tr>{list_row}<td><span class="link" onclick="showEdit('edit')">编辑</span> <span class="link" onclick="auditList()">审核</span></td></tr></table></div></div><div class="edit" id="edit"><div class="head"><h2 id="editTitle">{title} {no}</h2><div style="margin-left:auto"><button class="btn" onclick="backList()">返回列表</button><button class="btn">保存草稿</button><button class="btn primary" onclick="auditEdit()">提交/审核</button></div></div><div class="grid4">{form_fields}</div><div class="content"><table class="matrix"><tr>{detail_heads}<th>操作</th></tr>{detail_row}</table></div><div class="summary"><span>{summary}</span><span style="flex:1"></span><button class="btn primary" onclick="auditEdit()">审核</button></div></div></div></div><div id="toast" class="toast"></div><script>function showEdit(m){{list.style.display='none';edit.style.display='flex';editTitle.textContent=(m==='new'?'新建':'编辑')+' - {title} {no}'}}function backList(){{edit.style.display='none';list.style.display='flex'}}function auditEdit(){{toast('{audit}');}}function auditList(){{toast('列表选中单据已审核')}}function addLine(){{toast('已新增明细行')}}function toast(m){{let t=document.getElementById('toast');t.textContent=m;t.style.display='block';setTimeout(()=>t.style.display='none',2200)}}</script></body></html>'''
for file,(title,no,filters,cols,row,forms,detailCols,audit) in configs.items():
    filters_html=''.join(f'<label>{f}<input placeholder="{f}"></label>' for f in filters)
    list_heads=''.join(f'<th>{c}</th>' for c in cols)
    list_row=''.join(f'<td>{x}</td>' for x in row)
    form_fields=''.join(f'<label class="field">{f}<input value="{i+1 if f not in ["备注","调整原因","报损说明"] else ""}"></label>' for i,f in enumerate(forms))
    detail_heads=''.join(f'<th>{c}</th>' for c in detailCols)
    detail_row='<tr>'+''.join(f'<td contenteditable>{"" if i>0 else "示例商品"}</td>' for i,_ in enumerate(detailCols))+'<td><span class="link" onclick="this.closest(\'tr\').remove()">删除</span></td></tr>'
    summary='数量 <b>100</b>　金额 <b>¥1,000.00</b>　成本 <b>¥800.00</b>'
    html=TEMPLATE.format(title=title,no=no,filters=filters_html,list_heads=list_heads,list_row=list_row,form_fields=form_fields,detail_heads=detail_heads,detail_row=detail_row,summary=summary,audit=audit)
    (root/file).write_text(html,encoding='utf-8')
print('generated',len(configs),'bill pages')
